// @ts-nocheck
import { StructuredTaskSchema, StructuredTaskRequestSchema } from "../lib/ai/schemas.ts";
const GROQ_API_URL = "https://api.groq.com/openai/v1/chat/completions"
const GROQ_MODELS_URL = "https://api.groq.com/openai/v1/models"
/** Last-resort default. `env.GROQ_MODEL` (wrangler.jsonc var) always wins. */
const MODEL = "openai/gpt-oss-20b"

/* ===============================
   ✅ CALLER AUTHENTICATION
   =============================== */
/**
 * Validates the caller's Supabase access token — the same check `GET /auth/me`
 * has always performed, extracted so every clinician route can reuse it.
 *
 * Returns a `401` Response when the caller may not proceed, a `503` when Supabase
 * itself cannot be reached, or `null` when the request is authenticated.
 */
async function requireUser(request, env, cors, baseUrl) {
  const token = request.headers.get("Authorization")

  if (!token) {
    return { errorResponse: respond({ error: "Missing token" }, cors, 401) }
  }

  try {
    const res = await fetch(`${baseUrl}/auth/v1/user`, {
      method: "GET",
      headers: {
        "apikey": env.SUPABASE_ANON_KEY,
        "Authorization": token,
      },
    })

    if (res.ok) {
      const user = await res.json()
      return { user }
    }

    const data = await res.json().catch(() => null)

    return { errorResponse: respond(data || { error: "Invalid token" }, cors, 401) }
  } catch (err) {
    console.error("Auth check failed:", err)

    return { errorResponse: respond({ error: "Authentication unavailable" }, cors, 503) }
  }
}

/* ===============================
   ✅ CLIENT LINK SIGNING (HMAC-SHA256)
   =============================== */
/**
 * The client-facing pages (`/homework/:id`, `/practice/:id`) are deliberately
 * token-free so a client can open a shared link — which used to mean a raw UUID
 * was the only secret. Links are now signed and expiring:
 *
 *   /homework/<sessionId>?exp=<unixSeconds>&sig=<base64url>
 *
 * The signature covers `v1|sessionId|exp`, so a UUID alone opens nothing, the
 * expiry cannot be extended without the secret, and a link cannot be replayed
 * against a different session.
 *
 * `CLIENT_LINK_SECRET` is a Worker secret (never committed). It is *trimmed* on
 * read, so a trailing newline captured by `wrangler secret put` from a piped
 * value cannot desynchronise signing from verification.
 */
const CLIENT_LINK_DEFAULT_TTL_DAYS = 14
const CLIENT_LINK_MAX_TTL_DAYS = 30

function clientLinkSecret(env) {
  const raw = String(env?.CLIENT_LINK_SECRET || "").trim()

  return raw.length >= 16 ? raw : null
}

/** Where the client pages are served; falls back to the allowlisted app origin. */
function publicAppBase(env) {
  const configured = String(env?.PUBLIC_APP_URL || "").trim()

  if (configured) return configured.replace(/\/+$/, "")

  const first = String(env?.ALLOWED_ORIGINS || "").split(",")[0].trim()

  return first ? first.replace(/\/+$/, "") : ""
}

function base64UrlFromBytes(bytes) {
  const view = new Uint8Array(bytes)
  let binary = ""

  for (let i = 0; i < view.length; i++) {
    binary += String.fromCharCode(view[i])
  }

  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "")
}

function base64UrlToBytes(value) {
  const padded =
    value.replace(/-/g, "+").replace(/_/g, "/") +
    "=".repeat((4 - (value.length % 4)) % 4)
  const binary = atob(padded)
  const bytes = new Uint8Array(binary.length)

  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i)
  }

  return bytes
}

function clientLinkMessage(sessionId, exp) {
  return `v1|${sessionId}|${exp}`
}

async function hmacClientLinkKey(secret, usage) {
  return crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    [usage]
  )
}

async function signClientLink(sessionId, exp, secret) {
  const key = await hmacClientLinkKey(secret, "sign")

  const signature = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(clientLinkMessage(sessionId, exp))
  )

  return base64UrlFromBytes(signature)
}

/**
 * `{ ok, reason }`. Uses `crypto.subtle.verify`, which is constant-time — a
 * hand-rolled string comparison here would leak the signature byte by byte.
 */
async function verifyClientLink(sessionId, searchParams, env) {
  const secret = clientLinkSecret(env)

  if (!secret) {
    console.error(
      "CLIENT_LINK_SECRET missing or too short — client links are disabled"
    )

    return { ok: false, reason: "not_configured" }
  }

  const expRaw = searchParams.get("exp")
  const sig = searchParams.get("sig")

  if (!expRaw || !sig) return { ok: false, reason: "missing" }

  const exp = Number(expRaw)

  if (!Number.isInteger(exp)) return { ok: false, reason: "missing" }

  if (exp * 1000 <= Date.now()) return { ok: false, reason: "expired" }

  try {
    const key = await hmacClientLinkKey(secret, "verify")

    const valid = await crypto.subtle.verify(
      "HMAC",
      key,
      base64UrlToBytes(sig),
      new TextEncoder().encode(clientLinkMessage(sessionId, exp))
    )

    return valid ? { ok: true, exp } : { ok: false, reason: "bad_signature" }
  } catch {
    return { ok: false, reason: "bad_signature" }
  }
}

function clientLinkTtlDays(value) {
  const parsed = Number(value)

  if (!Number.isFinite(parsed) || parsed <= 0) {
    return CLIENT_LINK_DEFAULT_TTL_DAYS
  }

  return Math.min(Math.floor(parsed), CLIENT_LINK_MAX_TTL_DAYS)
}

export default {
  async fetch(request, env) {

    
    /* =========================
       ✅ CORS (ALLOWLIST)
       ========================= */
    // Echo back the request Origin only when it is explicitly allowlisted in
    // env.ALLOWED_ORIGINS (comma-separated). Anything else gets no CORS header
    // at all, so the browser blocks the response.
    //
    // TODO(clinician): ALLOWED_ORIGINS is not set on the `clinical-ai-backend`
    // Worker yet. Until it is, browsers get no CORS header and the dashboard
    // cannot call this Worker. Set it in wrangler.jsonc, e.g.
    //   "vars": { "GROQ_MODEL": "...", "ALLOWED_ORIGINS": "https://<dashboard-origin>,http://localhost:3000" }
    const requestOrigin = request.headers.get("Origin")

    const allowedOrigins = String(env.ALLOWED_ORIGINS || "")
      .split(",")
      .map((origin) => origin.trim())
      .filter(Boolean)

    const allowedOrigin =
      requestOrigin && allowedOrigins.includes(requestOrigin)
        ? requestOrigin
        : null

    const cors = {
      // Vary: Origin — this response varies by request Origin, so it must never be
      // served to a different Origin from a shared cache.
      ...(allowedOrigin
        ? {
            "Access-Control-Allow-Origin": allowedOrigin,
            "Vary": "Origin",
          }
        : {}),
      "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization, apikey, Prefer",
    }

    if (request.method === "OPTIONS") {
      return new Response(null, { headers: cors })
    }

    const url = new URL(request.url)
    const path = url.pathname
    const cleanPath = path.replace(/\/+$/, "")
    const method = request.method
    console.log("REQUEST", method, cleanPath)

    // ✅ Normalize base URL (prevents // issues)
    const baseUrl = env.SUPABASE_URL
      ? env.SUPABASE_URL.endsWith("/")
        ? env.SUPABASE_URL.slice(0, -1)
        : env.SUPABASE_URL
      : "http://localhost"

    const SUPABASE_URL = `${baseUrl}/rest/v1`

    const HEADERS = {
      "Content-Type": "application/json",
      "apikey": env.SUPABASE_SERVICE_ROLE_KEY,
      "Authorization": `Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,
      "Prefer": "return=representation"
    }
    const AUTH_HEADERS = {
      "Content-Type": "application/json",
      "apikey": env.SUPABASE_ANON_KEY,
    }
    /* =========================
       ✅ CALLER AUTHENTICATION GUARD
       ========================= */
    // Everything below is clinician-only except two things: the auth routes
    // themselves and the narrow, token-free client projection that
    // `/homework` and `/practice` read. `OPTIONS` already returned above, so CORS
    // preflight never needs a token.
    const isPublicRoute =
      cleanPath.startsWith("/auth/") ||
      cleanPath === "/client-homework" ||
      cleanPath.startsWith("/client-homework/")

    function devBypassUser(env, url) {
      const local = url.hostname === "localhost" || url.hostname === "127.0.0.1"
      if (env.DEV_AUTH_BYPASS === "1" && env.ENVIRONMENT === "development" && local) {
        console.warn("⚠️ DEV_AUTH_BYPASS active — synthetic user", env.DEV_AUTH_USER_ID)
        return { id: env.DEV_AUTH_USER_ID, email: "dev@localhost", dev_bypass: true }
      }
      return null
    }

    let authUser = null
    if (!isPublicRoute) {
      authUser = devBypassUser(env, url)
      if (!authUser) {
        const { errorResponse, user } = await requireUser(request, env, cors, baseUrl)
        if (errorResponse) return errorResponse
        authUser = user
      }
    }
    async function checkSessionAccess(sessionId) {
      if (!sessionId) return false;
      const sessionRes = await fetch(`${SUPABASE_URL}/sessions?id=eq.${sessionId}&select=client_id,case_formulations(client_id)`, { headers: HEADERS })
      if (!sessionRes.ok) return false;
      const sessionData = await sessionRes.json()
      if (!sessionData || !sessionData.length) return false;
      const sessionClientId = sessionData[0].client_id || sessionData[0].case_formulations?.client_id;
      return await checkClientAccess(sessionClientId);
    }
    async function checkClientAccess(clientId) {
      if (!clientId || !authUser?.id) return false
      const res = await fetch(`${SUPABASE_URL}/clinician_clients?clinician_id=eq.${authUser.id}&client_id=eq.${clientId}&select=id`, { headers: HEADERS })
      if (!res.ok) return false
      const data = await res.json()
      return Array.isArray(data) && data.length > 0
    }

    try {
/* =========================
   ✅ AUTH SIGNUP
========================= */
if (method === "POST" && cleanPath === "/auth/signup") {
  const body = await safeJson(request)

  if (
    !body?.email ||
    !body?.password ||
    !body?.first_name ||
    !body?.last_name
  ) {
    return respond(
      {
        error:
          "Missing first name, last name, email or password",
      },
      cors,
      400
    )
  }

  const signupRes = await fetch(
    `${baseUrl}/auth/v1/signup`,
    {
      method: "POST",
      headers: AUTH_HEADERS,
      body: JSON.stringify({
        email: body.email,
        password: body.password,

        data: {
          first_name: body.first_name,
          last_name: body.last_name,
          role: "clinician",
        },
      }),
    }
  )

  const signupData =
    await signupRes.json()

  if (!signupRes.ok) {
    return respond(
      signupData,
      cors,
      400
    )
  }

  return respond(
    {
      success: true,
      message:
        "Verification email sent",
    },
    cors
  )
}
/* =========================
   ✅ AUTH LOGIN
========================= */
if (method === "POST" && cleanPath === "/auth/login") {
  const body = await safeJson(request)

  if (!body?.email || !body?.password) {
    return respond(
      { error: "Missing email or password" },
      cors,
      400
    )
  }

  const loginRes = await fetch(
    `${baseUrl}/auth/v1/token?grant_type=password`,
    {
      method: "POST",
      headers: AUTH_HEADERS,
      body: JSON.stringify({
        email: body.email,
        password: body.password,
      }),
    }
  )

  const loginData = await loginRes.json()

  if (!loginRes.ok) {
    return respond(loginData, cors, 401)
  }

  return respond(
    {
      access_token:
        loginData.access_token,

      refresh_token:
        loginData.refresh_token,

      user: loginData.user,
    },
    cors
  )
}
/* =========================
   ✅ AUTH ME
========================= */
if (method === "GET" && cleanPath === "/auth/me") {
  const token =
    request.headers.get("Authorization");

  if (!token) {
    return respond(
      { error: "Missing token" },
      cors,
      401
    );
  }

  const meRes = await fetch(
    `${baseUrl}/auth/v1/user`,
    {
      method: "GET",
      headers: {
        "apikey": env.SUPABASE_ANON_KEY,
        "Authorization": token,
      },
    }
  );

  const meData = await meRes.json();

  if (!meRes.ok) {
    return respond(
      meData,
      cors,
      401
    );
  }

  const profileRes = await fetch(
    `${SUPABASE_URL}/profiles?id=eq.${meData.id}&select=*`,
    {
      headers: HEADERS,
    }
  );

  const profiles =
    await profileRes.json();

  return respond(
    {
      user: meData,
      profile: profiles?.[0] || null,
    },
    cors
  );
}
/* =========================
   ✅ GET ALL CLIENTS (FIXED)
   ========================= */
   if (method === "GET" && cleanPath === "/clients") {
    const mappingRes = await fetch(
      `${SUPABASE_URL}/clinician_clients?clinician_id=eq.${authUser.id}&select=client_id`,
      { headers: HEADERS }
    )
    if (!mappingRes.ok) throw new Error(await mappingRes.text())
    
    const mappingData = await mappingRes.json()
    const clientIds = (Array.isArray(mappingData) ? mappingData : []).map(m => m.client_id).filter(Boolean)

    if (clientIds.length === 0) {
      return respond([], cors)
    }

    let res = await fetch(
      `${SUPABASE_URL}/clients?id=in.(${clientIds.join(",")})&select=id,full_name`,
      { headers: HEADERS }
    )
  
    if (!res.ok) {
      const text = await res.text()
      if (isMissingColumnError(text)) {
        res = await fetch(
          `${SUPABASE_URL}/clients?id=in.(${clientIds.join(",")})&select=id,first_name,last_name`,
          { headers: HEADERS }
        )
        if (!res.ok) {
          throw new Error(await res.text())
        }
      } else {
        throw new Error(text)
      }
    }
  
    let data
    try {
      data = await res.json()
    } catch {
      return respond([], cors)
    }
  
    return respond(
      (Array.isArray(data) ? data : []).map(c => ({
        id: c.id,
        name: c.full_name || [c.first_name, c.last_name].filter(Boolean).join(" ") || `Client ${c.id.slice(0, 6)}`
      })),
      cors
    )
    
  }
  
        /* =========================
        ✅ CREATE CLIENT
        ========================= */
      if (method === "POST" && cleanPath === "/clients") {
        const body = await safeJson(request)

        const payload = buildClientPayload(body, true)

        if (!Object.keys(payload).length) {
          return respond(
            { error: "Missing client details (name or contact fields)" },
            cors,
            400
          )
        }

        const row = await writeClientRow(SUPABASE_URL, HEADERS, "POST", null, payload)

        await fetch(`${SUPABASE_URL}/clinician_clients`, {
          method: "POST",
          headers: HEADERS,
          body: JSON.stringify({
            clinician_id: authUser.id,
            client_id: row.id
          })
        })

        return respond(row, cors)
      }


      /* =========================
         ✅ CREATE CASE
         ========================= */
         if (method === "POST" && cleanPath === "/cases") {
          const body = await safeJson(request)
        
          if (!body?.clientId) {
            return respond({ error: "Missing clientId" }, cors, 400)
          }

          if (!(await checkClientAccess(body.clientId))) {
            return respond({ error: "Client not found or access denied" }, cors, 404)
          }
        
          // ✅ Count existing cases for this client
          const countRes = await fetch(
            `${SUPABASE_URL}/case_formulations?client_id=eq.${body.clientId}&select=id`,
            { headers: HEADERS }
          )
        
          const existing = await countRes.json()
          const nextNumber = (Array.isArray(existing) ? existing.length : 0) + 1
        
          const name = body?.name || `Case ${nextNumber}`
        
          const res = await fetch(`${SUPABASE_URL}/case_formulations`, {
            method: "POST",
            headers: HEADERS,
            body: JSON.stringify({
              client_id: body.clientId,
              name,
            }),
          })
        
          if (!res.ok) throw new Error(await res.text())
        
          const data = await res.json()
          return respond(data?.[0] || data, cors)
        }

      /* =========================
         ✅ CREATE SESSION
         ========================= */
         if (method === "POST" && cleanPath === "/sessions") {
          const body = await safeJson(request)
        
          if (!body?.caseId) {
            return respond({ error: "Missing caseId" }, cors, 400)
          }

          // ✅ Resolve the owning client from the case: callers often send only caseId.
          const caseRes = await fetch(
            `${SUPABASE_URL}/case_formulations?id=eq.${encodeURIComponent(body.caseId)}&select=id,client_id`,
            { headers: HEADERS }
          )

          if (!caseRes.ok) throw new Error(await caseRes.text())

          const caseRows = await caseRes.json()

          if (!Array.isArray(caseRows) || caseRows.length === 0) {
            return respond({ error: "Case not found" }, cors, 404)
          }

          // ✅ The case row is the source of truth for client_id; body.clientId only
          // covers legacy case rows whose own client_id is null.
          const clientId = caseRows[0].client_id || body.clientId || null
          if (!(await checkClientAccess(clientId))) {
            return respond({ error: "Client not found or access denied" }, cors, 404)
          }
        
          // ✅ Count existing sessions for this case
          const countRes = await fetch(
            `${SUPABASE_URL}/sessions?case_id=eq.${body.caseId}&select=id`,
            { headers: HEADERS }
          )
        
          const existing = await countRes.json()
          const nextNumber = (Array.isArray(existing) ? existing.length : 0) + 1
        
          const name = body?.name || `Session ${nextNumber}`
        
          const res = await fetch(`${SUPABASE_URL}/sessions`, {
            method: "POST",
            headers: HEADERS,
            body: JSON.stringify({
              case_id: body.caseId,
              client_id: clientId,
              name,
            }),
          })
        
          if (!res.ok) throw new Error(await res.text())
        
          const data = await res.json()
          return respond(data?.[0] || data, cors)
        }

      /* =========================
         ✅ DELETE CASE
         ========================= */
      if (method === "DELETE" && cleanPath.startsWith("/cases/")) {
        const id = path.split("/")[2]

        if (!id) {
          return respond({ error: "Missing caseId" }, cors, 400)
        }

        const caseRes = await fetch(`${SUPABASE_URL}/case_formulations?id=eq.${id}&select=client_id`, { headers: HEADERS })
        if (!caseRes.ok) throw new Error(await caseRes.text())
        const caseData = await caseRes.json()
        if (!caseData || !caseData.length) {
          return respond({ error: "Case not found" }, cors, 404)
        }
        if (!(await checkClientAccess(caseData[0].client_id))) {
          return respond({ error: "Access denied" }, cors, 403)
        }

        const res = await fetch(
          `${SUPABASE_URL}/case_formulations?id=eq.${id}`,
          { method: "DELETE", headers: HEADERS }
        )

        if (!res.ok && res.status !== 204) {
          throw new Error(await res.text())
        }

        return respond({ success: true }, cors)
      }

      /* =========================
         ✅ DELETE SESSION
         ========================= */
      if (method === "DELETE" && cleanPath.startsWith("/sessions/")) {
        const id = path.split("/")[2]

        if (!id) {
          return respond({ error: "Missing sessionId" }, cors, 400)
        }

        const sessionRes = await fetch(`${SUPABASE_URL}/sessions?id=eq.${id}&select=client_id,case_formulations(client_id)`, { headers: HEADERS })
        if (!sessionRes.ok) throw new Error(await sessionRes.text())
        const sessionData = await sessionRes.json()
        if (!sessionData || !sessionData.length) {
          return respond({ error: "Session not found" }, cors, 404)
        }
        const sessionClientId = sessionData[0].client_id || sessionData[0].case_formulations?.client_id;
        if (!(await checkClientAccess(sessionClientId))) {
          return respond({ error: "Access denied" }, cors, 403)
        }

        const res = await fetch(
          `${SUPABASE_URL}/sessions?id=eq.${id}`,
          { method: "DELETE", headers: HEADERS }
        )

        if (!res.ok && res.status !== 204) {
          throw new Error(await res.text())
        }

        return respond({ success: true }, cors)
      }

      /* =========================
          ✅ RENAME CLIENT
          ========================= */
        if (method === "PATCH" && cleanPath.startsWith("/clients/")) {
          const id = path.split("/")[2]
          const body = await safeJson(request)

          if (!id) {
            return respond({ error: "Missing clientId" }, cors, 400)
          }

          if (!(await checkClientAccess(id))) {
            return respond({ error: "Client not found or access denied" }, cors, 404)
          }

          const payload = buildClientPayload(body, true)

          if (!Object.keys(payload).length) {
            return respond(
              { error: "No client fields to update" },
              cors,
              400
            )
          }

          await writeClientRow(SUPABASE_URL, HEADERS, "PATCH", id, payload)

          return respond({ success: true }, cors)
        }

        /* =========================
          ✅ RENAME CASE
          ========================= */
        if (method === "PATCH" && cleanPath.startsWith("/cases/")) {
          const id = path.split("/")[2]
          const body = await safeJson(request)

          if (!body?.name) {
            return respond({ error: "Missing name" }, cors, 400)
          }

          const caseRes = await fetch(`${SUPABASE_URL}/case_formulations?id=eq.${id}&select=client_id`, { headers: HEADERS })
          if (!caseRes.ok) throw new Error(await caseRes.text())
          const caseData = await caseRes.json()
          if (!caseData || !caseData.length) {
            return respond({ error: "Case not found" }, cors, 404)
          }
          if (!(await checkClientAccess(caseData[0].client_id))) {
            return respond({ error: "Access denied" }, cors, 403)
          }

          const res = await fetch(
            `${SUPABASE_URL}/case_formulations?id=eq.${id}`,
            {
              method: "PATCH",
              headers: HEADERS,
              body: JSON.stringify({
  name: body.name
}),
            }
          )

          if (!res.ok) throw new Error(await res.text())

          return respond({ success: true }, cors)
        }

        /* =========================
          ✅ UPDATE SESSION (name + clinical content)
          ========================= */
        if (method === "PATCH" && cleanPath.startsWith("/sessions/")) {
          const id = cleanPath.split("/")[2]
          const body = await safeJson(request)

          if (!id) {
            return respond({ error: "Missing sessionId" }, cors, 400)
          }

          const sessionRes = await fetch(`${SUPABASE_URL}/sessions?id=eq.${id}&select=client_id,case_formulations(client_id)`, { headers: HEADERS })
          if (!sessionRes.ok) throw new Error(await sessionRes.text())
          const sessionData = await sessionRes.json()
          if (!sessionData || !sessionData.length) {
            return respond({ error: "Session not found" }, cors, 404)
          }
          const sessionClientId = sessionData[0].client_id || sessionData[0].case_formulations?.client_id;
          if (!(await checkClientAccess(sessionClientId))) {
            return respond({ error: "Access denied" }, cors, 403)
          }

          const patch = buildSessionPatch(body)
          if (!Object.keys(patch).length) {
            return respond({ error: "No fields to update" }, cors, 400)
          }

          const row = await patchSessionRow(id, patch, SUPABASE_URL, HEADERS)
          
          if (!row) {
            return respond({ error: "Session not found" }, cors, 404)
          }

          await saveSessionVersion(id, patch, SUPABASE_URL, HEADERS)

          return respond(formatSessionRow(row), cors)
        }

      /* =========================
         ✅ MINT CLIENT LINK (clinician only)
         ========================= */
      // Issues the signed, expiring link for the token-free client pages. This
      // path is NOT in the public list above, so it is behind `requireUser`:
      // only a signed-in clinician can produce a link.
      if (method === "GET" && cleanPath.startsWith("/client-link/")) {
        const sessionId = cleanPath.split("/")[2]

        if (!sessionId || sessionId.length < 10) {
          return respond({ error: "Invalid session ID" }, cors, 400)
        }

        const sessionRes = await fetch(`${SUPABASE_URL}/sessions?id=eq.${sessionId}&select=client_id,case_formulations(client_id)`, { headers: HEADERS })
        if (!sessionRes.ok) throw new Error(await sessionRes.text())
        const sessionData = await sessionRes.json()
        if (!sessionData || !sessionData.length) {
          return respond({ error: "Session not found" }, cors, 404)
        }
        const sessionClientId = sessionData[0].client_id || sessionData[0].case_formulations?.client_id;
        if (!(await checkClientAccess(sessionClientId))) {
          return respond({ error: "Access denied" }, cors, 403)
        }

        const secret = clientLinkSecret(env)

        if (!secret) {
          return respond({ error: "Client links are not configured" }, cors, 503)
        }

        const base = publicAppBase(env)

        if (!base) {
          return respond({ error: "PUBLIC_APP_URL is not configured" }, cors, 500)
        }

        const row = await fetchSessionRow(sessionId, SUPABASE_URL, HEADERS)

        if (!row) {
          return respond({ error: "Session not found" }, cors, 404)
        }

        const ttlDays = clientLinkTtlDays(url.searchParams.get("ttlDays"))
        const exp = Math.floor(Date.now() / 1000) + ttlDays * 86400
        const sig = await signClientLink(sessionId, exp, secret)
        const query = `exp=${exp}&sig=${encodeURIComponent(sig)}`

        return respond(
          {
            sessionId,
            ttlDays,
            exp,
            expiresAt: new Date(exp * 1000).toISOString(),
            homeworkUrl: `${base}/homework/${sessionId}?${query}`,
            practiceUrl: `${base}/practice/${sessionId}?${query}`,
          },
          cors
        )
      }

      /* =========================
      ✅ CLIENT HOMEWORK ROUTE (MERGED)
      ========================= */
    if (method === "GET" && cleanPath.startsWith("/client-homework/")) {
      const sessionId = cleanPath.split("/")[2]

      if (!sessionId || sessionId.length < 10) {
        return respond({ error: "Invalid session ID" }, cors, 400)
      }

      const link = await verifyClientLink(sessionId, url.searchParams, env)

      if (!link.ok) {
        console.warn(
          `Client link rejected (${link.reason}) for ${String(sessionId).slice(0, 8)}…`
        )

        return respond(
          {
            error:
              "This link is invalid or has expired. Please ask your clinician for a new one.",
          },
          cors,
          403
        )
      }

      const row = await fetchSessionRow(sessionId, SUPABASE_URL, HEADERS)

      if (!row) {
        return respond({ error: "Session not found" }, cors, 404)
      }

      let practiceHomework = []

      if (
        row.practice_package &&
        Array.isArray(row.practice_package.homework) &&
        row.practice_package.homework.length > 0
      ) {
        practiceHomework = row.practice_package.homework
      } else if (Array.isArray(row.homework) && row.homework.length > 0) {
        practiceHomework = row.homework
      } else if (row.practice_package && typeof row.practice_package === "object") {
        practiceHomework = extractHomeworkFromPracticePackage(row.practice_package)
      }

      // No other source is consulted: `practice_task_submissions` has no
      // session_id, so any lookup there can only be client-scoped and could
      // surface another session's content through this session's link.

      return respond({
        sessionId: row.id,
        title: row.name,
        homework: Array.isArray(row.homework) ? row.homework : [],
        quiz: Array.isArray(row.quiz) ? row.quiz : [],
        vignette: row.vignette || "",
        // Deliberately narrow: this route is public, so it must never carry
        // session_notes, analysis or riskFlags.
        practiceHomework,
        // The clinician's chosen activity, from THIS row only (allowlisted).
        practiceTask: projectClientPracticeTask(row.practice_package),
      }, cors)
    }

/* =========================
         ✅ GET SESSION
         ========================= */
      if (method === "GET" && cleanPath.startsWith("/sessions/")) {
        const id = cleanPath.split("/")[2]

        if (!id) {
          return respond({ error: "Missing sessionId" }, cors, 400)
        }

        const sessionRes = await fetch(`${SUPABASE_URL}/sessions?id=eq.${id}&select=client_id,case_formulations(client_id)`, { headers: HEADERS })
        if (!sessionRes.ok) throw new Error(await sessionRes.text())
        const sessionData = await sessionRes.json()
        if (!sessionData || !sessionData.length) {
          return respond({ error: "Session not found" }, cors, 404)
        }
        const sessionClientId = sessionData[0].client_id || sessionData[0].case_formulations?.client_id;
        if (!(await checkClientAccess(sessionClientId))) {
          return respond({ error: "Access denied" }, cors, 403)
        }

        const row = await fetchSessionRow(id, SUPABASE_URL, HEADERS)
        if (!row) {
          return respond({ error: "Session not found" }, cors, 404)
        }

        return respond(formatSessionRow(row), cors)
      }

      /* =========================
        ✅ GET ALL SESSIONS (HISTORY)
        ========================= */
        if (method === "GET" && cleanPath === "/sessions") {
          const clientId = url.searchParams.get("clientId")
          const sessionId = url.searchParams.get("sessionId")

          if (clientId) {
            if (!(await checkClientAccess(clientId))) {
              return respond({ error: "Client not found or access denied" }, cors, 404)
            }
          }

          if (sessionId && !clientId) {
            const sessionRes = await fetch(`${SUPABASE_URL}/sessions?id=eq.${sessionId}&select=client_id,case_formulations(client_id)`, { headers: HEADERS })
            if (!sessionRes.ok) throw new Error(await sessionRes.text())
            const sessionData = await sessionRes.json()
            if (!sessionData || !sessionData.length) {
              return respond({ error: "Session not found" }, cors, 404)
            }
            const sessionClientId = sessionData[0].client_id || sessionData[0].case_formulations?.client_id;
            if (!(await checkClientAccess(sessionClientId))) {
              return respond({ error: "Access denied" }, cors, 403)
            }
          }

          let query = `${SUPABASE_URL}/sessions?select=${SESSION_FULL_SELECT}&order=created_at.desc`

          if (clientId) {
            query += `&client_id=eq.${clientId}`
          } else if (sessionId) {
            query += `&id=eq.${sessionId}`
          } else {
            const mappingRes = await fetch(
              `${SUPABASE_URL}/clinician_clients?clinician_id=eq.${authUser.id}&select=client_id`,
              { headers: HEADERS }
            )
            if (!mappingRes.ok) throw new Error(await mappingRes.text())
            const mappingData = await mappingRes.json()
            const clientIds = (Array.isArray(mappingData) ? mappingData : []).map(m => m.client_id).filter(Boolean)
            
            if (clientIds.length === 0) {
              return respond([], cors)
            }
            query += `&client_id=in.(${clientIds.join(",")})`
          }

          const res = await fetch(query, { headers: HEADERS })

          if (!res.ok) {
            throw new Error(await res.text())
          }

          const data = await res.json()

          // ✅ format all rows
          const formatted = Array.isArray(data)
            ? data.map(formatSessionRow)
            : []

          return respond(formatted, cors)
        }

      /* =========================
         ✅ RESTORED ROUTE (IMPORTANT)
         ========================= */
      if (method === "GET" && cleanPath === "/latest-session") {
        const sessionId = url.searchParams.get("sessionId")

        if (!sessionId) {
          return respond({
            sessionNotes: "",
            lastUpdated: null,
          }, cors)
        }

        const sessionRes = await fetch(`${SUPABASE_URL}/sessions?id=eq.${sessionId}&select=client_id,case_formulations(client_id)`, { headers: HEADERS })
        if (!sessionRes.ok) throw new Error(await sessionRes.text())
        const sessionData = await sessionRes.json()
        if (!sessionData || !sessionData.length) {
          return respond({ error: "Session not found" }, cors, 404)
        }
        const sessionClientId = sessionData[0].client_id || sessionData[0].case_formulations?.client_id;
        if (!(await checkClientAccess(sessionClientId))) {
          return respond({ error: "Access denied" }, cors, 403)
        }

        const row = await fetchSessionRow(sessionId, SUPABASE_URL, HEADERS)
        if (!row) {
          return respond({ error: "Session not found" }, cors, 404)
        }

        return respond(formatSessionRow(row), cors)
      }
      /*=========================
          ✅ /client/history (materials assigned to one client)
      =========================*/
      if (method === "GET" && cleanPath === "/client/history") {
        const clientId = url.searchParams.get("clientId")

        if (!clientId) {
          return respond({ error: "Missing clientId" }, cors, 400)
        }
        
        if (!(await checkClientAccess(clientId))) {
          return respond({ error: "Client not found or access denied" }, cors, 404)
        }

        // Sessions hang off cases and `sessions.client_id` is often NULL, so join via cases.
        const res = await fetch(
          `${SUPABASE_URL}/case_formulations?client_id=eq.${clientId}&select=id,name,sessions(${SESSION_FULL_SELECT})`,
          { headers: HEADERS }
        )

        if (!res.ok) throw new Error(await res.text())

        const cases = await res.json()

        const materials = (Array.isArray(cases) ? cases : [])
          .flatMap((c) =>
            (c.sessions || []).map((s) => ({ ...s, name: s.name || c.name }))
          )
          .filter((s) => s.vignette || s.practice_package)
          .map(formatClientMaterial)
          .sort((a, b) =>
            String(b.createdAt || "").localeCompare(String(a.createdAt || ""))
          )

        return respond(materials, cors)
      }

      /*=========================
          ✅ /client/:id (single client tree)
      =========================*/
      if (method === "GET" && cleanPath.startsWith("/client/")) {
        const id = cleanPath.split("/")[2]

        if (!(await checkClientAccess(id))) {
          return respond({ error: "Client not found or access denied" }, cors, 404)
        }

        const res = await fetch(
          `${SUPABASE_URL}/clients?id=eq.${id}&select=id,full_name,case_formulations(id,name,sessions(id,name))`,
          { headers: HEADERS }
        )

        if (!res.ok) throw new Error(await res.text())

        const data = await res.json()

        if (!data?.length) {
          return respond({ error: "Client not found" }, cors, 404)
        }

        return respond({
          id: data[0].id,
          name: data[0].full_name,
          cases: data[0].case_formulations || [],
        }, cors)
      }



      /* =========================
         ✅ CLIENT WORKSHEET SUBMISSION
         ========================= */
      if (method === "POST" && cleanPath === "/client/worksheet") {
        const body = await safeJson(request)

        const clientId = body?.clientId || null
        const sessionId = body?.sessionId || body?.vignetteId || null
        const answers = body?.answers || null

        if (!clientId || !answers) {
          return respond(
            { error: "Missing clientId or answers" },
            cors,
            400
          )
        }

        if (!(await checkClientAccess(clientId))) {
          return respond({ error: "Client not found or access denied" }, cors, 404)
        }

        const res = await fetch(`${SUPABASE_URL}/worksheet_submissions`, {
          method: "POST",
          headers: HEADERS,
          body: JSON.stringify({
            client_id: clientId,
            session_id: sessionId,
            answers,
          }),
        })

        if (!res.ok) throw new Error(await res.text())

        const data = await res.json()

        return respond({ success: true, submission: data?.[0] || null }, cors)
      }

      /* =========================
         ✅ AI DIAGNOSTICS
         ========================= */
      if (method === "GET" && cleanPath === "/ai/models") {
        const configured = resolveModel(env)

        const res = await fetch(GROQ_MODELS_URL, {
          headers: {
            Authorization: `Bearer ${env.GROQ_API_KEY}`,
          },
        })

        const text = await res.text()

        if (!res.ok) {
          return respond(
            {
              ok: false,
              model: configured,
              groqStatus: res.status,
              detail: extractGroqErrorMessage(text),
            },
            cors
          )
        }

        let data = null

        try {
          data = JSON.parse(text)
        } catch {
          data = null
        }

        const available = Array.isArray(data?.data)
          ? data.data.map((m) => m?.id).filter(Boolean)
          : []

        return respond(
          {
            ok: true,
            model: configured,
            configuredAvailable: available.includes(configured),
            count: available.length,
            available,
          },
          cors
        )
      }

      if (method === "GET" && cleanPath === "/ai/health") {
        const model = resolveModel(env)

        const result = await callGroq(
          [{ role: "user", content: "Reply with the single word: ok" }],
          env,
          0
        )

        if (!result.ok) {
          return respond(
            {
              ok: false,
              model,
              groqStatus: result.error.status,
              detail: result.error.message,
            },
            cors
          )
        }

        return respond(
          {
            ok: true,
            model,
            sample: String(result.content).trim().slice(0, 80),
          },
          cors
        )
      }

      if (method === "GET" && cleanPath === "/ai/probe") {
        const model = resolveModel(env)
        const which = url.searchParams.get("prompt") || "analyze"
        const notes =
          url.searchParams.get("notes") ||
          "Client reports low mood and avoids social contact."
        const modality = url.searchParams.get("modality") || "cbt"

        const debug = {}

        let outcome

        if (which === "generate" || which === "vignette") {
          outcome = await handleGenerate(
            notes,
            modality,
            env,
            cors,
            false,
            true,
            debug
          )
        } else if (which === "package" || which === "practice-package") {
          outcome = await handleGeneratePracticePackage(
            notes,
            modality,
            env,
            cors,
            false,
            true,
            debug
          )
        } else {
          outcome = await handleAnalyze(notes, env, cors, false, true, debug)
        }

        const groqError = debug.groqError || null
        // "parse_ok" now means *accepted*: the answer parsed AND matched the
        // contract. A valid-JSON-but-partial answer is a failure, not a pass.
        const parseOk = Boolean(debug.usable)

        return respond(
          {
            ok: !groqError && parseOk,
            prompt: which,
            model: debug.model || model,
            parse_ok: parseOk,
            finish_reason: debug.finishReason || null,
            attempts: debug.attempts || 1,
            reason: debug.reason || null,
            parse_error: debug.parseError || null,
            strategy: debug.strategy || null,
            raw_sample: debug.raw ? String(debug.raw).slice(0, 600) : null,
            parsed: outcome instanceof Response ? null : outcome,
            groq_error: groqError,
            failure: groqError
              ? "groq_error"
              : parseOk
                ? null
                : "parse_error",
          },
          cors
        )
      }

      /* =========================
   ✅ TASK SUBMISSION ROUTES
   New routes MUST stay above the catch-all "if (method === 'POST')" AI block.
   ========================= */

      /* ------------------------------------------------------------------
         POST /tasks/submissions
         Upsert a practice-task submission in `draft` status.

         Body (JSON):
           { id?, client_id, task_type, form_data }
           (practitioner_id is enforced from authUser.id)

         • `id` omitted  → INSERT with status = 'draft'
         • `id` present  → UPDATE where status = 'draft' (refuses other statuses)
         Returns the upserted row.
      ------------------------------------------------------------------ */
      if (method === "POST" && cleanPath === "/tasks/submissions") {
        const body = await safeJson(request)

        if (!body?.client_id || !body?.task_type || !body?.form_data) {
          return respond({ error: "Missing required fields: client_id, task_type, form_data" }, cors, 400)
        }

        if (!(await checkClientAccess(body.client_id))) {
          return respond({ error: "Client not found or access denied" }, cors, 404)
        }

        let row

        if (body.id) {
          // UPDATE: only allow overwriting drafts
          const checkRes = await fetch(
            `${SUPABASE_URL}/practice_task_submissions?id=eq.${encodeURIComponent(body.id)}&select=id,status`,
            { headers: HEADERS }
          )
          if (!checkRes.ok) throw new Error(await checkRes.text())
          const existing = await checkRes.json()

          if (!existing?.length) {
            return respond({ error: "Submission not found" }, cors, 404)
          }
          if (existing[0].status !== "draft") {
            return respond({ error: "Only draft submissions can be updated" }, cors, 409)
          }

          const patchRes = await fetch(
            `${SUPABASE_URL}/practice_task_submissions?id=eq.${encodeURIComponent(body.id)}`,
            {
              method: "PATCH",
              headers: HEADERS,
              body: JSON.stringify({
                task_type: body.task_type,
                form_data: body.form_data,
                updated_at: new Date().toISOString(),
              }),
            }
          )
          if (!patchRes.ok) throw new Error(await patchRes.text())
          const patchData = await patchRes.json()
          row = Array.isArray(patchData) ? patchData[0] : patchData
        } else {
          // INSERT new draft
          const insertRes = await fetch(`${SUPABASE_URL}/practice_task_submissions`, {
            method: "POST",
            headers: HEADERS,
            body: JSON.stringify({
              client_id: body.client_id,
              practitioner_id: authUser.id,
              task_type: body.task_type,
              form_data: body.form_data,
              status: "draft",
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString(),
            }),
          })
          if (!insertRes.ok) throw new Error(await insertRes.text())
          const insertData = await insertRes.json()
          row = Array.isArray(insertData) ? insertData[0] : insertData
        }

        return respond(row, cors)
      }

      /* ------------------------------------------------------------------
         POST /tasks/submissions/:id/commit
         Transition draft → pending_practitioner_review.
         Writes a status_audit_log row atomically.
         Body: (empty — submissionId is in the path)
         Returns the updated submission row.
      ------------------------------------------------------------------ */
      if (method === "POST" && /^\/tasks\/submissions\/[^/]+\/commit$/.test(cleanPath)) {
        const submissionId = cleanPath.split("/")[3]

        // Load existing row for access check and status gate
        const loadRes = await fetch(
          `${SUPABASE_URL}/practice_task_submissions?id=eq.${encodeURIComponent(submissionId)}&select=*`,
          { headers: HEADERS }
        )
        if (!loadRes.ok) throw new Error(await loadRes.text())
        const existing = await loadRes.json()

        if (!existing?.length) {
          return respond({ error: "Submission not found" }, cors, 404)
        }

        const submission = existing[0]

        if (!(await checkClientAccess(submission.client_id))) {
          return respond({ error: "Access denied" }, cors, 403)
        }

        if (submission.status !== "draft") {
          return respond(
            { error: `Cannot commit: status is '${submission.status}', expected 'draft'` },
            cors,
            409
          )
        }

        const now = new Date().toISOString()

        // Write status transition
        const patchRes = await fetch(
          `${SUPABASE_URL}/practice_task_submissions?id=eq.${encodeURIComponent(submissionId)}`,
          {
            method: "PATCH",
            headers: HEADERS,
            body: JSON.stringify({
              status: "pending_practitioner_review",
              updated_at: now,
            }),
          }
        )
        if (!patchRes.ok) throw new Error(await patchRes.text())
        const updatedData = await patchRes.json()
        const updated = Array.isArray(updatedData) ? updatedData[0] : updatedData

        // Append audit log row (best-effort — failure does NOT roll back the status change)
        try {
          await fetch(`${SUPABASE_URL}/status_audit_log`, {
            method: "POST",
            headers: HEADERS,
            body: JSON.stringify({
              submission_id: submissionId,
              previous_status: "draft",
              new_status: "pending_practitioner_review",
              changed_by_user_id: authUser.id,
              changed_at: now,
            }),
          })
        } catch (auditErr) {
          console.error("status_audit_log insert failed (non-fatal):", auditErr)
        }

        return respond(updated, cors)
      }

      /* ------------------------------------------------------------------
         GET /tasks/submissions/:id/bundle
         Returns the full review bundle:
           { submission, reflections[], practitioner_notes[] }
         The practitioner must have access to the submission's owning client.
      ------------------------------------------------------------------ */
      if (method === "GET" && /^\/tasks\/submissions\/[^/]+\/bundle$/.test(cleanPath)) {
        const submissionId = cleanPath.split("/")[3]

        const submissionRes = await fetch(
          `${SUPABASE_URL}/practice_task_submissions?id=eq.${encodeURIComponent(submissionId)}&select=*`,
          { headers: HEADERS }
        )
        if (!submissionRes.ok) throw new Error(await submissionRes.text())
        const submissionData = await submissionRes.json()

        if (!submissionData?.length) {
          return respond({ error: "Submission not found" }, cors, 404)
        }

        const submission = submissionData[0]

        if (!(await checkClientAccess(submission.client_id))) {
          return respond({ error: "Access denied" }, cors, 403)
        }

        // Fetch reflections, notes, and audit log in parallel
        const [reflectionsRes, notesRes, auditRes] = await Promise.all([
          fetch(
            `${SUPABASE_URL}/client_reflections?submission_id=eq.${encodeURIComponent(submissionId)}&select=*&order=created_at.asc`,
            { headers: HEADERS }
          ),
          fetch(
            `${SUPABASE_URL}/submission_practitioner_notes?submission_id=eq.${encodeURIComponent(submissionId)}&select=*&order=created_at.asc`,
            { headers: HEADERS }
          ),
          fetch(
            `${SUPABASE_URL}/status_audit_log?submission_id=eq.${encodeURIComponent(submissionId)}&select=*&order=changed_at.asc`,
            { headers: HEADERS }
          ),
        ])

        if (!reflectionsRes.ok) throw new Error(await reflectionsRes.text())
        if (!notesRes.ok) throw new Error(await notesRes.text())

        const reflections = await reflectionsRes.json()
        const practitioner_notes = await notesRes.json()
        // audit log is best-effort — don't fail the whole bundle if it errors
        const audit_log = auditRes.ok ? await auditRes.json() : []

        return respond({ submission, reflections, practitioner_notes, audit_log }, cors)
      }

      /* ------------------------------------------------------------------
         POST /tasks/submissions/:id/notes
         Append a practitioner note to a submission (append-only).

         Body (JSON): { practitioner_id, notes }
         Returns the newly created note row.
      ------------------------------------------------------------------ */
      if (method === "POST" && /^\/tasks\/submissions\/[^/]+\/notes$/.test(cleanPath)) {
        const submissionId = cleanPath.split("/")[3]
        const body = await safeJson(request)

        if (!body?.notes || typeof body.notes !== "string" || !body.notes.trim()) {
          return respond({ error: "Missing or empty 'notes' field" }, cors, 400)
        }

        // Load submission to gate on client access
        const submissionRes = await fetch(
          `${SUPABASE_URL}/practice_task_submissions?id=eq.${encodeURIComponent(submissionId)}&select=client_id`,
          { headers: HEADERS }
        )
        if (!submissionRes.ok) throw new Error(await submissionRes.text())
        const submissionData = await submissionRes.json()

        if (!submissionData?.length) {
          return respond({ error: "Submission not found" }, cors, 404)
        }

        if (!(await checkClientAccess(submissionData[0].client_id))) {
          return respond({ error: "Access denied" }, cors, 403)
        }

        const insertRes = await fetch(`${SUPABASE_URL}/submission_practitioner_notes`, {
          method: "POST",
          headers: HEADERS,
          body: JSON.stringify({
            submission_id: submissionId,
            practitioner_id: body.practitioner_id ?? authUser.id,
            notes: body.notes.trim(),
            created_at: new Date().toISOString(),
          }),
        })
        if (!insertRes.ok) throw new Error(await insertRes.text())
        const noteData = await insertRes.json()
        const note = Array.isArray(noteData) ? noteData[0] : noteData

        return respond(note, cors)
      }

      /* ------------------------------------------------------------------
         POST /tasks/submissions/:id/approve
         Practitioner Gateway — approve a submission.

         Transitions status: pending_practitioner_review → approved
         Sets reviewed_at to the current timestamp.
         Appends a status_audit_log row (best-effort).

         The DB trigger enforces immutability after this transition:
         any subsequent PATCH on an approved row is rejected at the Postgres
         level. This route does NOT attempt to write the row again after the
         PATCH succeeds.

         Returns the updated submission row.
      ------------------------------------------------------------------ */
      if (method === "POST" && /^\/tasks\/submissions\/[^/]+\/approve$/.test(cleanPath)) {
        const submissionId = cleanPath.split("/")[3]

        const loadRes = await fetch(
          `${SUPABASE_URL}/practice_task_submissions?id=eq.${encodeURIComponent(submissionId)}&select=*`,
          { headers: HEADERS }
