          return respond({ error: "Image upload failed", detail }, cors, 502)
        }

        // ── Derive the public URL ───────────────────────────────────────
        const imageUrl = `${storageUrl}/storage/v1/object/public/client-reflections/${storagePath}`

        // ── Insert client_reflections row (best-effort) ─────────────────
        try {
